export const AYAH = [
  {"id":"A01","title":"The best provision","ar":"اَلْحَجُّ اَشْهُرٌ مَّعْلُوْمٰتٌۚ فَمَنْ فَرَضَ فِيْهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوْقَۙ وَلَا جِدَالَ فِي الْحَجِّؕ وَمَا تَفْعَلُوْا مِنْ خَيْرٍ يَّعْلَمْهُ اللّٰهُؕؔ وَتَزَوَّدُوْا فَاِنَّ خَيْرَ الزَّادِ التَّقْوٰيؗ وَاتَّقُوْنِ يٰٓاُولِي الْاَلْبَابِ ۝١٩٧","en":"The pilgrimage is (in) the well-known months, and whoever is minded to perform the pilgrimage therein (let him remember that) there is (to be) no lewdness nor abuse nor angry conversation on the pilgrimage. And whatsoever good ye do Allah knoweth it. So make provision for yourselves (Hereafter); for the best provision is to ward off evil. Therefore keep your duty unto Me, O men of understanding.","src":"Qurʾān 2:197 (Al-Baqarah, \"The Cow\")","draft":false,"status":"approved"},
  {"id":"A02","title":"Never lose hope","ar":"قُلْ يٰعِبَادِيَ الَّذِيْنَ اَسْرَفُوْا عَلٰٓي اَنْفُسِهِمْ لَا تَقْنَطُوْا مِنْ رَّحْمَةِ اللّٰهِؕ اِنَّ اللّٰهَ يَغْفِرُ الذُّنُوْبَ جَمِيْعًاؕ اِنَّهٗ هُوَ الْغَفُوْرُ الرَّحِيْمُ ۝٥٣","en":"Say: O My slaves who have been prodigal to their own hurt! Despair not of the mercy of Allah, Who forgiveth all sins. Lo! He is the Forgiving, the Merciful.","src":"Qurʾān 39:53 (Az-Zumar, \"The Groups\")","draft":false,"status":"approved"},
  {"id":"A03","title":"Until the very end","ar":"وَاعْبُدْ رَبَّكَ حَتّٰي يَاْتِيَكَ الْيَقِيْنُ ۝٩٩ࣖ","en":"And serve thy Lord till the Inevitable cometh unto thee.","src":"Qurʾān 15:99 (Al-Hijr, \"The Rock\")","draft":false,"status":"approved"},
  {"id":"A04","title":"Remember Me","ar":"فَاذْكُرُوْنِيْٓ اَذْكُرْكُمْ وَاشْكُرُوْا لِيْ وَلَا تَكْفُرُوْنِ ۝١٥٢ࣖ","en":"Therefore remember Me, I will remember you. Give thanks to Me, and reject not Me.","src":"Qurʾān 2:152 (Al-Baqarah, \"The Cow\")","draft":false,"status":"approved"},
  {"id":"A05","title":"Turning back at once","ar":"وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً اَوْ ظَلَمُوْٓا اَنْفُسَهُمْ ذَكَرُوا اللّٰهَ فَاسْتَغْفَرُوْا لِذُنُوْبِهِمْࣕ وَمَنْ يَّغْفِرُ الذُّنُوْبَ اِلَّا اللّٰهُࣕࣞ وَلَمْ يُصِرُّوْا عَلٰي مَا فَعَلُوْا وَهُمْ يَعْلَمُوْنَ ۝١٣٥","en":"And those who, when they do an evil thing or wrong themselves, remember Allah and implore forgiveness for their sins—Who forgiveth sins save Allah only?—and will not knowingly repeat (the wrong) they did.","src":"Qurʾān 3:135 (Āl ʿImrān, \"The Family of Imraan\")","draft":false,"status":"approved"},
  {"id":"A06","title":"Glad tidings for the patient","ar":"وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِّنَ الْخَوْفِ وَالْجُوْعِ وَنَقْصٍ مِّنَ الْاَمْوَالِ وَالْاَنْفُسِ وَالثَّمَرٰتِؕ وَبَشِّرِ الصّٰبِرِيْنَ ۝١٥٥ۙ الَّذِيْنَ اِذَا͏ٓ اَصَابَتْهُمْ مُّصِيْبَةٌۙ قَالُوْٓا اِنَّا لِلّٰهِ وَاِنَّا͏ٓ اِلَيْهِ رٰجِعُوْنَ ۝١٥٦ؕ اُولٰ࢜ىِٕكَ عَلَيْهِمْ صَلَوٰتٌ مِّنْ رَّبِّهِمْ وَرَحْمَةٌࣞ وَاُولٰ࢜ىِٕكَ هُمُ الْمُهْتَدُوْنَ ۝١٥٧","en":"And surely We shall try you with something of fear and hunger, and loss of wealth and lives and crops; but give glad tidings to the steadfast, Who say, when a misfortune striketh them: Lo! we are Allah's and lo! unto Him we are returning. Such are they on whom are blessings from their Lord, and mercy. Such are the rightly guided.","src":"Qurʾān 2:155–157 (Al-Baqarah, \"The Cow\")","draft":false,"status":"approved"},
  {"id":"A07","title":"Thanks brings more","ar":"وَاِذْ تَاَذَّنَ رَبُّكُمْ لَىِٕنْ شَكَرْتُمْ لَاَزِيْدَنَّكُمْ وَلَىِٕنْ كَفَرْتُمْ اِنَّ عَذَابِيْ لَشَدِيْدٌ ۝٧","en":"And when your Lord proclaimed: If ye give thanks, I will give you more; but if ye are thankless, lo! My punishment is dire.","src":"Qurʾān 14:7 (Ibrāhīm, \"Abraham\")","draft":false,"status":"approved"},
  {"id":"A08","title":"He is enough","ar":"وَّيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُؕ وَمَنْ يَّتَوَكَّلْ عَلَي اللّٰهِ فَهُوَ حَسْبُهٗؕ اِنَّ اللّٰهَ بَالِغُ اَمْرِهٖؕ قَدْ جَعَلَ اللّٰهُ لِكُلِّ شَيْءٍ قَدْرًا ۝٣","en":"And will provide for him from (a quarter) whence he hath no expectation. And whosoever putteth his trust in Allah, He will suffice him. Lo! Allah bringeth His command to pass. Allah hath set a measure for all things.","src":"Qurʾān 65:3 (At-Talāq, \"Divorce\")","draft":false,"status":"approved"},
  {"id":"A09","title":"He is near","ar":"وَاِذَا سَاَلَكَ عِبَادِيْ عَنِّيْ فَاِنِّيْ قَرِيْبٌؕ اُجِيْبُ دَعْوَةَ الدَّاعِ اِذَا دَعَانِۙ فَلْيَسْتَجِيْبُوْا لِيْ وَلْيُو͏ٔ͏ْمِنُوْا بِيْ لَعَلَّهُمْ يَرْشُدُوْنَ ۝١٨٦","en":"And when My servants question thee concerning Me, then surely I am nigh. I answer the prayer of the suppliant when he crieth unto Me. So let them hear My call and let them trust in Me, in order that they may be led aright.","src":"Qurʾān 2:186 (Al-Baqarah, \"The Cow\")","draft":false,"status":"approved"},
  {"id":"A10","title":"What you send ahead","ar":"يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَلْتَنْظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍۚ وَاتَّقُوا اللّٰهَؕ اِنَّ اللّٰهَ خَبِيْرٌۢ بِمَا تَعْمَلُوْنَ ۝١٨","en":"O ye who believe! Observe your duty to Allah. And let every soul look to that which it sendeth on before for the morrow. And observe your duty to Allah. Lo! Allah is Informed of what ye do.","src":"Qurʾān 59:18 (Al-Hashr, \"The Exile\")","draft":false,"status":"approved"},
  {"id":"A11","title":"With hardship, ease","ar":"فَاِنَّ مَعَ الْعُسْرِ يُسْرًا ۝٥ۙ اِنَّ مَعَ الْعُسْرِ يُسْرًا ۝٦ؕ","en":"But lo! with hardship goeth ease, Lo! with hardship goeth ease;","src":"Qurʾān 94:5–6 (Ash-Sharh, \"The Consolation\")","draft":false,"status":"approved"},
  {"id":"A12","title":"Those who stand firm","ar":"اِنَّ الَّذِيْنَ قَالُوْا رَبُّنَا اللّٰهُ ثُمَّ اسْتَقَامُوْا تَتَنَزَّلُ عَلَيْهِمُ الْمَلٰ࢜ىِٕكَةُ اَلَّا تَخَافُوْا وَلَا تَحْزَنُوْا وَاَبْشِرُوْا بِالْجَنَّةِ الَّتِيْ كُنْتُمْ تُوْعَدُوْنَ ۝٣٠ نَحْنُ اَوْلِيٰ࢜و͏ٔ͏ُكُمْ فِي الْحَيٰوةِ الدُّنْيَا وَفِي الْاٰخِرَةِۚ وَلَكُمْ فِيْهَا مَا تَشْتَهِيْٓ اَنْفُسُكُمْ وَلَكُمْ فِيْهَا مَا تَدَّعُوْنَ ۝٣١ؕ","en":"Lo! those who say: Our Lord is Allah, and afterward are upright, the angels descend upon them, saying: Fear not nor grieve, but hear good tidings of the paradise which ye are promised. We are your protecting friends in the life of the world and in the Hereafter. There ye will have (all) that your souls desire, and there ye will have (all) for which ye pray.","src":"Qurʾān 41:30–31 (Fussilat, \"Explained in detail\")","draft":false,"status":"approved"},
  {"id":"A13","title":"Hearts at rest","ar":"اَلَّذِيْنَ اٰمَنُوْا وَتَطْمَىِٕنُّ قُلُوْبُهُمْ بِذِكْرِ اللّٰهِؕ اَلَا بِذِكْرِ اللّٰهِ تَطْمَىِٕنُّ الْقُلُوْبُ ۝٢٨ؕ","en":"Who have believed and whose hearts have rest in the remembrance of Allah. Verily in the remembrance of Allah do hearts find rest!","src":"Qurʾān 13:28 (Ar-Raʿd, \"The Thunder\")","draft":false,"status":"approved"},
  {"id":"A14","title":"Always ready to forgive","ar":"وَاِنِّيْ لَغَفَّارٌ لِّمَنْ تَابَ وَاٰمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدٰي ۝٨٢","en":"And lo! verily I am Forgiving toward him who repenteth and believeth and doeth good, and afterward walketh aright.","src":"Qurʾān 20:82 (Tā Hā, \"Taa-Haa\")","draft":false,"status":"approved"},
  {"id":"A15","title":"Reward without measure","ar":"قُلْ يٰعِبَادِ الَّذِيْنَ اٰمَنُوا اتَّقُوْا رَبَّكُمْؕ لِلَّذِيْنَ اَحْسَنُوْا فِيْ هٰذِهِ الدُّنْيَا حَسَنَةٌؕ وَاَرْضُ اللّٰهِ وَاسِعَةٌؕ اِنَّمَا يُوَفَّي الصّٰبِرُوْنَ اَجْرَهُمْ بِغَيْرِ حِسَابٍ ۝١٠","en":"Say: O My bondmen who believe! Observe your duty to your Lord. For those who do good in this world there is good, and Allah's earth is spacious. Verily the steadfast will be paid their wages without stint.","src":"Qurʾān 39:10 (Az-Zumar, \"The Groups\")","draft":false,"status":"approved"},
  {"id":"A16","title":"Blessings beyond counting","ar":"وَاِنْ تَعُدُّوْا نِعْمَةَ اللّٰهِ لَا تُحْصُوْهَاؕ اِنَّ اللّٰهَ لَغَفُوْرٌ رَّحِيْمٌ ۝١٨","en":"And if ye would count the favour of Allah ye cannot reckon it. Lo! Allah is indeed Forgiving, Merciful.","src":"Qurʾān 16:18 (An-Nahl, \"The Bee\")","draft":false,"status":"approved"},
  {"id":"A17","title":"Let the believers trust","ar":"اَللّٰهُ لَا͏ٓ اِلٰهَ اِلَّا هُوَؕ وَعَلَي اللّٰهِ فَلْيَتَوَكَّلِ الْمُو͏ٔ͏ْمِنُوْنَ ۝١٣","en":"Allah! There is no God save Him. In Allah, therefore, let believers put their trust.","src":"Qurʾān 64:13 (At-Taghābun, \"Mutual Disillusion\")","draft":false,"status":"approved"},
  {"id":"A18","title":"Tenfold for every good","ar":"مَنْ جَا࢜ءَ بِالْحَسَنَةِ فَلَهٗ عَشْرُ اَمْثَالِهَاۚ وَمَنْ جَا࢜ءَ بِالسَّيِّي͏ٔ͏َةِ فَلَا يُجْزٰٓي اِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُوْنَ ۝١٦٠","en":"Whoso bringeth a good deed will receive tenfold the like thereof, while whoso bringeth an ill-deed will be awarded but the like thereof; and they will not be wronged.","src":"Qurʾān 6:160 (Al-Anʿām, \"The Cattle\")","draft":false,"status":"approved"},
  {"id":"A19","title":"Better and more lasting","ar":"بَلْ تُو͏ٔ͏ْثِرُوْنَ الْحَيٰوةَ الدُّنْيَا ۝١٦ۚۖ وَالْاٰخِرَةُ خَيْرٌ وَّاَبْقٰي ۝١٧ؕ","en":"But ye prefer the life of the world Although the Hereafter is better and more lasting.","src":"Qurʾān 87:16–17 (Al-Aʿlā, \"The Most High\")","draft":false,"status":"approved"},
  {"id":"A20","title":"Mercy He has written","ar":"وَاِذَا جَا࢜ءَكَ الَّذِيْنَ يُو͏ٔ͏ْمِنُوْنَ بِاٰيٰتِنَا فَقُلْ سَلٰمٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلٰي نَفْسِهِ الرَّحْمَةَۙ اَنَّهٗ مَنْ عَمِلَ مِنْكُمْ سُوْ࢜ءًاۢ بِجَهَالَةٍ ثُمَّ تَابَ مِنْۢ بَعْدِهٖ وَاَصْلَحَ فَاَنَّهٗ غَفُوْرٌ رَّحِيْمٌ ۝٥٤","en":"And when those who believe in Our revelations come unto thee, say: Peace be unto you! Your Lord hath prescribed for Himself mercy, that whoso of you doeth evil through ignorance and repenteth afterward thereof and doeth right, (for him) lo! He is Forgiving, Merciful.","src":"Qurʾān 6:54 (Al-Anʿām, \"The Cattle\")","draft":false,"status":"approved"},
  {"id":"A21","title":"As best you can","ar":"فَاتَّقُوا اللّٰهَ مَا اسْتَطَعْتُمْ وَاسْمَعُوْا وَاَطِيْعُوْا وَاَنْفِقُوْا خَيْرًا لِّاَنْفُسِكُمْؕ وَمَنْ يُّوْقَ شُحَّ نَفْسِهٖ فَاُولٰ࢜ىِٕكَ هُمُ الْمُفْلِحُوْنَ ۝١٦","en":"So keep your duty to Allah as best ye can, and listen, and obey, and spend; that is better for your souls. And whoso is saved from his own greed, such are the successful.","src":"Qurʾān 64:16 (At-Taghābun, \"Mutual Disillusion\")","draft":false,"status":"approved"},
  {"id":"A22","title":"Remember Him much","ar":"يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اذْكُرُوا اللّٰهَ ذِكْرًا كَثِيْرًا ۝٤١ۙ وَّسَبِّحُوْهُ بُكْرَةً وَّاَصِيْلًا ۝٤٢ هُوَ الَّذِيْ يُصَلِّيْ عَلَيْكُمْ وَمَلٰ࢜ىِٕكَتُهٗ لِيُخْرِجَكُمْ مِّنَ الظُّلُمٰتِ اِلَي النُّوْرِؕ وَكَانَ بِالْمُو͏ٔ͏ْمِنِيْنَ رَحِيْمًا ۝٤٣","en":"O ye who believe! Remember Allah with much remembrance. And glorify Him early and late. He it is Who blesseth you, and His angels (bless you), that He may bring you forth from darkness unto light; and He is ever Merciful to the believers.","src":"Qurʾān 33:41–43 (Al-Ahzāb, \"The Clans\")","draft":false,"status":"approved"},
  {"id":"A23","title":"Sins turned to good","ar":"اِلَّا مَنْ تَابَ وَاٰمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَاُولٰ࢜ىِٕكَ يُبَدِّلُ اللّٰهُ سَيِّاٰتِهِمْ حَسَنٰتٍؕ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًا ۝٧٠","en":"Save him who repenteth and believeth and doth righteous work; as for such, Allah will change their evil deeds to good deeds. Allah is ever Forgiving, Merciful.","src":"Qurʾān 25:70 (Al-Furqān, \"The Criterion\")","draft":false,"status":"approved"},
  {"id":"A24","title":"Endure and hold firm","ar":"يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اصْبِرُوْا وَصَابِرُوْا وَرَابِطُوْاࣞ وَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُفْلِحُوْنَ ۝٢٠٠ࣖ","en":"O ye who believe! Endure, outdo all others in endurance, be ready, and observe your duty to Allah, in order that ye may succeed.","src":"Qurʾān 3:200 (Āl ʿImrān, \"The Family of Imraan\")","draft":false,"status":"approved"},
  {"id":"A25","title":"Thanks is for your own good","ar":"وَلَقَدْ اٰتَيْنَا لُقْمٰنَ الْحِكْمَةَ اَنِ اشْكُرْ لِلّٰهِؕ وَمَنْ يَّشْكُرْ فَاِنَّمَا يَشْكُرُ لِنَفْسِهٖۚ وَمَنْ كَفَرَ فَاِنَّ اللّٰهَ غَنِيٌّ حَمِيْدٌ ۝١٢","en":"And verily We gave Luqman wisdom, saying: Give thanks unto Allah; and whosoever giveth thanks, he giveth thanks for (the good of) his soul. And whosoever refuseth - Lo! Allah is Absolute, Owner of Praise.","src":"Qurʾān 31:12 (Luqmān, \"Luqman\")","draft":false,"status":"approved"},
  {"id":"A26","title":"Every provision is with Allah","ar":"وَمَا مِنْ دَا࢜بَّةٍ فِي الْاَرْضِ اِلَّا عَلَي اللّٰهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَاؕ كُلٌّ فِيْ كِتٰبٍ مُّبِيْنٍ ۝٦","en":"And there is not a beast in the earth but the sustenance thereof dependeth on Allah. He knoweth its habitation and its repository. All is in a clear Record.","src":"Qurʾān 11:6 (Hūd, \"Hud\")","draft":false,"status":"approved"},
  {"id":"A27","title":"A lighter load","ar":"يُرِيْدُ اللّٰهُ اَنْ يُّخَفِّفَ عَنْكُمْۚ وَخُلِقَ الْاِنْسَانُ ضَعِيْفًا ۝٢٨","en":"Allah would make the burden light for you, for man was created weak.","src":"Qurʾān 4:28 (An-Nisāʾ, \"The Women\")","draft":false,"status":"approved"},
  {"id":"A28","title":"Deeds that last","ar":"اَلْمَالُ وَالْبَنُوْنَ زِيْنَةُ الْحَيٰوةِ الدُّنْيَاۚ وَالْبٰقِيٰتُ الصّٰلِحٰتُ خَيْرٌ عِنْدَ رَبِّكَ ثَوَابًا وَّخَيْرٌ اَمَلًا ۝٤٦","en":"Wealth and children are an ornament of the life of the world. But the good deeds which endure are better in thy Lord's sight for reward, and better in respect of hope.","src":"Qurʾān 18:46 (Al-Kahf, \"The Cave\")","draft":false,"status":"approved"},
  {"id":"A29","title":"Do not despair","ar":"يٰبَنِيَّ اذْهَبُوْا فَتَحَسَّسُوْا مِنْ يُّوْسُفَ وَاَخِيْهِ وَلَا تَايْـٔ͏َسُوْا مِنْ رَّوْحِ اللّٰهِؕ اِنَّهٗ لَا يَايْـٔ͏َسُ مِنْ رَّوْحِ اللّٰهِ اِلَّا الْقَوْمُ الْكٰفِرُوْنَ ۝٨٧","en":"Go, O my sons, and ascertain concerning Joseph and his brother, and despair not of the Spirit of Allah. Lo! none despaireth of the Spirit of Allah save disbelieving folk.","src":"Qurʾān 12:87 (Yūsuf, \"Joseph\")","draft":false,"status":"approved"},
  {"id":"A30","title":"Hidden joy","ar":"تَتَجَافٰي جُنُوْبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُوْنَ رَبَّهُمْ خَوْفًا وَّطَمَعًاؗ وَّمِمَّا رَزَقْنٰهُمْ يُنْفِقُوْنَ ۝١٦ فَلَا تَعْلَمُ نَفْسٌ مَّا͏ٓ اُخْفِيَ لَهُمْ مِّنْ قُرَّةِ اَعْيُنٍۚ جَزَا࢜ءًۢ بِمَا كَانُوْا يَعْمَلُوْنَ ۝١٧","en":"Who forsake their beds to cry unto their Lord in fear and hope, and spend of that We have bestowed on them. No soul knoweth what is kept hid for them of joy, as a reward for what they used to do.","src":"Qurʾān 32:16–17 (As-Sajdah, \"The Prostration\")","draft":false,"status":"approved"},
  {"id":"A31","title":"Morning and evening","ar":"وَاذْكُرْ رَّبَّكَ فِيْ نَفْسِكَ تَضَرُّعًا وَّخِيْفَةً وَّدُوْنَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْاٰصَالِ وَلَا تَكُنْ مِّنَ الْغٰفِلِيْنَ ۝٢٠٥","en":"And do thou (O Muhammad) remember thy Lord within thyself humbly and with awe, below thy breath, at morn and evening. And be not thou of the neglectful.","src":"Qurʾān 7:205 (Al-Aʿrāf, \"The Heights\")","draft":false,"status":"approved"},
  {"id":"A32","title":"You will find Him Forgiving","ar":"وَمَنْ يَّعْمَلْ سُوْ࢜ءًا اَوْ يَظْلِمْ نَفْسَهٗ ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُوْرًا رَّحِيْمًا ۝١١٠","en":"Yet whoso doeth evil or wrongeth his own soul, then seeketh pardon of Allah, will find Allah Forgiving, Merciful.","src":"Qurʾān 4:110 (An-Nisāʾ, \"The Women\")","draft":false,"status":"approved"},
  {"id":"A33","title":"In Our sight","ar":"وَاصْبِرْ لِحُكْمِ رَبِّكَ فَاِنَّكَ بِاَعْيُنِنَا وَسَبِّحْ بِحَمْدِ رَبِّكَ حِيْنَ تَقُوْمُ ۝٤٨ۙ وَمِنَ الَّيْلِ فَسَبِّحْهُ وَاِدْبَارَ النُّجُوْمِ ۝٤٩ࣖ","en":"So wait patiently (O Muhammad) for thy Lord's decree, for surely thou art in Our sight; and hymn the praise of thy Lord when thou uprisest, And in the night-time also hymn His praise, and at the setting of the stars.","src":"Qurʾān 52:48–49 (At-Tūr, \"The Mount\")","draft":false,"status":"approved"},
  {"id":"A34","title":"Night and day","ar":"اَللّٰهُ الَّذِيْ جَعَلَ لَكُمُ الَّيْلَ لِتَسْكُنُوْا فِيْهِ وَالنَّهَارَ مُبْصِرًاؕ اِنَّ اللّٰهَ لَذُوْ فَضْلٍ عَلَي النَّاسِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَشْكُرُوْنَ ۝٦١","en":"Allah it is Who hath appointed for you night that ye may rest therein, and day for seeing. Lo! Allah is a Lord of bounty for mankind, yet most of mankind give not thanks.","src":"Qurʾān 40:61 (Ghāfir, \"The Forgiver\")","draft":false,"status":"approved"},
  {"id":"A35","title":"He sees you stand","ar":"وَتَوَكَّلْ عَلَي الْعَزِيْزِ الرَّحِيْمِ ۝٢١٧ۙ الَّذِيْ يَرٰىكَ حِيْنَ تَقُوْمُ ۝٢١٨ۙ وَتَقَلُّبَكَ فِي السّٰجِدِيْنَ ۝٢١٩","en":"And put thy trust in the Mighty, the Merciful. Who seeth thee when thou standest up (to pray) And (seeth) thine abasement among those who fall prostrate (in worship).","src":"Qurʾān 26:217–219 (Ash-Shuʿarāʾ, \"The Poets\")","draft":false,"status":"approved"},
  {"id":"A36","title":"Gentle with His servants","ar":"اَللّٰهُ لَطِيْفٌۢ بِعِبَادِهٖ يَرْزُقُ مَنْ يَّشَا࢜ءُۚ وَهُوَ الْقَوِيُّ الْعَزِيْزُ ۝١٩ࣖ","en":"Allah is gracious unto His slaves. He provideth for whom He will. And He is the Strong, the Mighty.","src":"Qurʾān 42:19 (Ash-Shūrā, \"Consultation\")","draft":false,"status":"approved"},
  {"id":"A37","title":"Found with Allah","ar":"وَاَقِيْمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَؕ وَمَا تُقَدِّمُوْا لِاَنْفُسِكُمْ مِّنْ خَيْرٍ تَجِدُوْهُ عِنْدَ اللّٰهِؕ اِنَّ اللّٰهَ بِمَا تَعْمَلُوْنَ بَصِيْرٌ ۝١١٠","en":"Establish worship, and pay the poor-due; and whatever of good ye send before (you) for your souls, ye will find it with Allah. Lo! Allah is Seer of what ye do.","src":"Qurʾān 2:110 (Al-Baqarah, \"The Cow\")","draft":false,"status":"approved"},
  {"id":"A38","title":"Signs of mercy","ar":"فَانْظُرْ اِلٰٓي اٰثٰرِ رَحْمَتِ اللّٰهِ كَيْفَ يُحْيِ الْاَرْضَ بَعْدَ مَوْتِهَاؕ اِنَّ ذٰلِكَ لَمُحْيِ الْمَوْتٰىۚ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ ۝٥٠","en":"Look, therefore, at the prints of Allah's mercy (in creation): how He quickeneth the earth after her death. Lo! He verily is the Quickener of the Dead, and He is Able to do all things.","src":"Qurʾān 30:50 (Ar-Rūm, \"The Romans\")","draft":false,"status":"approved"},
  {"id":"A39","title":"Steadfast in worship","ar":"رَبُّ السَّمٰوٰتِ وَالْاَرْضِ وَمَا بَيْنَهُمَا فَاعْبُدْهُ وَاصْطَبِرْ لِعِبَادَتِهٖؕ هَلْ تَعْلَمُ لَهٗ سَمِيًّا ۝٦٥ࣖ","en":"Lord of the heavens and the earth and all that is between them! Therefor, worship thou Him and be thou steadfast in His service. Knowest thou one that can be named along with Him?","src":"Qurʾān 19:65 (Maryam, \"Mary\")","draft":false,"status":"approved"},
  {"id":"A40","title":"The greatest remembrance","ar":"اُتْلُ مَا͏ٓ اُوْحِيَ اِلَيْكَ مِنَ الْكِتٰبِ وَاَقِمِ الصَّلٰوةَؕ اِنَّ الصَّلٰوةَ تَنْهٰي عَنِ الْفَحْشَا࢜ءِ وَالْمُنْكَرِؕ وَلَذِكْرُ اللّٰهِ اَكْبَرُؕ وَاللّٰهُ يَعْلَمُ مَا تَصْنَعُوْنَ ۝٤٥","en":"Recite that which hath been inspired in thee of the Scripture, and establish worship. Lo! worship preserveth from lewdness and iniquity, but verily remembrance of Allah is more important. And Allah knoweth what ye do.","src":"Qurʾān 29:45 (Al-ʿAnkabūt, \"The Spider\")","draft":false,"status":"approved"},
  {"id":"A41","title":"Seek forgiveness","ar":"فَقُلْتُ اسْتَغْفِرُوْا رَبَّكُمْؕ اِنَّهٗ كَانَ غَفَّارًا ۝١٠ۙ يُّرْسِلِ السَّمَا࢜ءَ عَلَيْكُمْ مِّدْرَارًا ۝١١ۙ وَّيُمْدِدْكُمْ بِاَمْوَالٍ وَّبَنِيْنَ وَيَجْعَلْ لَّكُمْ جَنّٰتٍ وَّيَجْعَلْ لَّكُمْ اَنْهٰرًا ۝١٢ؕ","en":"And I have said: Seek pardon of your Lord. Lo! He was ever Forgiving. He will let loose the sky for you in plenteous rain, And will help you with wealth and sons, and will assign unto you Gardens and will assign unto you rivers.","src":"Qurʾān 71:10–12 (Nūh, \"Noah\")","draft":false,"status":"approved"},
  {"id":"A42","title":"What remains","ar":"مَا عِنْدَكُمْ يَنْفَدُ وَمَا عِنْدَ اللّٰهِ بَاقٍؕ وَلَنَجْزِيَنَّ الَّذِيْنَ صَبَرُوْٓا اَجْرَهُمْ بِاَحْسَنِ مَا كَانُوْا يَعْمَلُوْنَ ۝٩٦","en":"That which ye have wasteth away, and that which Allah hath remaineth. And verily We shall pay those who are steadfast a recompense in proportion to the best of what they used to do.","src":"Qurʾān 16:96 (An-Nahl, \"The Bee\")","draft":false,"status":"approved"},
  {"id":"A43","title":"Thankful and believing","ar":"مَا يَفْعَلُ اللّٰهُ بِعَذَابِكُمْ اِنْ شَكَرْتُمْ وَاٰمَنْتُمْؕ وَكَانَ اللّٰهُ شَاكِرًا عَلِيْمًا ۝١٤٧","en":"What concern hath Allah for your punishment if ye are thankful (for His mercies) and believe (in Him)? Allah was ever Responsive, Aware.","src":"Qurʾān 4:147 (An-Nisāʾ, \"The Women\")","draft":false,"status":"approved"},
  {"id":"A44","title":"Trust in Allah","ar":"وَّتَوَكَّلْ عَلَي اللّٰهِؕ وَكَفٰي بِاللّٰهِ وَكِيْلًا ۝٣","en":"And put thy trust in Allah, for Allah is sufficient as Trustee.","src":"Qurʾān 33:3 (Al-Ahzāb, \"The Clans\")","draft":false,"status":"approved"},
  {"id":"A45","title":"Never forsaken","ar":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٰي ۝٣ؕ وَلَلْاٰخِرَةُ خَيْرٌ لَّكَ مِنَ الْاُوْلٰي ۝٤ؕ وَلَسَوْفَ يُعْطِيْكَ رَبُّكَ فَتَرْضٰي ۝٥ؕ","en":"Thy Lord hath not forsaken thee nor doth He hate thee, And verily the latter portion will be better for thee than the former, And verily thy Lord will give unto thee so that thou wilt be content.","src":"Qurʾān 93:3–5 (Ad-Duhā, \"The Morning Hours\")","draft":false,"status":"approved"},
  {"id":"A46","title":"Not an atom lost","ar":"فَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَّرَهٗ ۝٧ؕ","en":"And whoso doeth good an atom's weight will see it then,","src":"Qurʾān 99:7 (Az-Zalzalah, \"The Earthquake\")","draft":false,"status":"approved"},
  {"id":"A47","title":"A healing and a mercy","ar":"يٰٓاَيُّهَا النَّاسُ قَدْ جَا࢜ءَتْكُمْ مَّوْعِظَةٌ مِّنْ رَّبِّكُمْ وَشِفَا࢜ءٌ لِّمَا فِي الصُّدُوْرِ࣢ۙ وَهُدًي وَّرَحْمَةٌ لِّلْمُو͏ٔ͏ْمِنِيْنَ ۝٥٧ قُلْ بِفَضْلِ اللّٰهِ وَبِرَحْمَتِهٖ فَبِذٰلِكَ فَلْيَفْرَحُوْاؕ هُوَ خَيْرٌ مِّمَّا يَجْمَعُوْنَ ۝٥٨","en":"O mankind! There hath come unto you an exhortation from your Lord, a balm for that which is in the breasts, a guidance and a mercy for believers. Say: In the bounty of Allah and in His mercy: therein let them rejoice. It is better than what they hoard.","src":"Qurʾān 10:57–58 (Yūnus, \"Jonas\")","draft":false,"status":"approved"},
  {"id":"A48","title":"Strive and be guided","ar":"وَالَّذِيْنَ جَاهَدُوْا فِيْنَا لَنَهْدِيَنَّهُمْ سُبُلَنَاؕ وَاِنَّ اللّٰهَ لَمَعَ الْمُحْسِنِيْنَ ۝٦٩ࣖ","en":"As for those who strive in Us, We surely guide them to Our paths, and lo! Allah is with the good.","src":"Qurʾān 29:69 (Al-ʿAnkabūt, \"The Spider\")","draft":false,"status":"approved"},
  {"id":"A49","title":"Devote yourself","ar":"وَاذْكُرِ اسْمَ رَبِّكَ وَتَبَتَّلْ اِلَيْهِ تَبْتِيْلًا ۝٨ؕ رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ لَا͏ٓ اِلٰهَ اِلَّا هُوَ فَاتَّخِذْهُ وَكِيْلًا ۝٩","en":"So remember the name of thy Lord and devote thyself with a complete devotion— Lord of the East and the West; there is no God save Him; so choose thou Him alone for thy defender—","src":"Qurʾān 73:8–9 (Al-Muzzammil, \"The Enshrouded One\")","draft":false,"status":"approved"},
  {"id":"A50","title":"He accepts repentance","ar":"وَهُوَ الَّذِيْ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهٖ وَيَعْفُوْا عَنِ السَّيِّاٰتِ وَيَعْلَمُ مَا تَفْعَلُوْنَ ۝٢٥ۙ","en":"And He it is Who accepteth repentance from His bondmen, and pardoneth the evil deeds, and knoweth what ye do,","src":"Qurʾān 42:25 (Ash-Shūrā, \"Consultation\")","draft":false,"status":"approved"},
  {"id":"A51","title":"Patience and prayer","ar":"وَاسْتَعِيْنُوْا بِالصَّبْرِ وَالصَّلٰوةِؕ وَاِنَّهَا لَكَبِيْرَةٌ اِلَّا عَلَي الْخٰشِعِيْنَ ۝٤٥ۙ الَّذِيْنَ يَظُنُّوْنَ اَنَّهُمْ مُّلٰقُوْا رَبِّهِمْ وَاَنَّهُمْ اِلَيْهِ رٰجِعُوْنَ ۝٤٦ࣖ","en":"Seek help in patience and prayer; and truly it is hard save for the humble-minded, Who know that they will have to meet their Lord, and that unto Him they are returning.","src":"Qurʾān 2:45–46 (Al-Baqarah, \"The Cow\")","draft":false,"status":"approved"},
  {"id":"A52","title":"Good deeds erase bad","ar":"وَاَقِمِ الصَّلٰوةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِّنَ الَّيْلِؕ اِنَّ الْحَسَنٰتِ يُذْهِبْنَ السَّيِّاٰتِؕ ذٰلِكَ ذِكْرٰي لِلذّٰكِرِيْنَ ۝١١٤ۚ وَاصْبِرْ فَاِنَّ اللّٰهَ لَا يُضِيْعُ اَجْرَ الْمُحْسِنِيْنَ ۝١١٥","en":"Establish worship at the two ends of the day and in some watches of the night. Lo! good deeds annul ill-deeds. This is reminder for the mindful. And have patience, (O Muhammad), for lo! Allah loseth not the wages of the good.","src":"Qurʾān 11:114–115 (Hūd, \"Hud\")","draft":false,"status":"approved"},
];
